widgets_values:
{
  "task": "Create a highly coherent 2x2 cinematic storyboard grid in a 16:9 widescreen canvas.",
  "format": {
    "canvas_ratio": "16:9",
    "layout": "one single 16:9 image divided into four equal rectangular widescreen panels",
    "panel_structure": "2x2 grid",
    "bbox_order": "ymin_xmin_ymax_xmax",
    "panels": {
      "top_left": [0, 0, 495, 495],
      "top_right": [0, 505, 495, 1000],
      "bottom_left": [505, 0, 1000, 495],
      "bottom_right": [505, 505, 1000, 1000]
    },
    "divider": "thin clean black gutters between panels",
    "text_policy": "the generated image itself contains no readable words, no captions, no subtitles, no logos, no panel numbers"
  },
  "global_scene": {
    "world": "a bright magical candy valley",
    "atmosphere": "chocolate rivers, sugar roads, cake towers, candy hills, cotton candy clouds, pastel dessert plants, warm sunrise glow, magical sparkle particles",
    "style": "whimsical cinematic fantasy, polished animation-film aesthetic, clean composition, soft realistic lighting, warm pastel palette, charming and magical"
  },
  "character_consistency": {
    "subject": "the same solo child explorer must appear clearly in all four panels",
    "appearance": "young boy, soft brown hair, bright curious eyes, gentle expressive face",
    "outfit": "cream explorer outfit, short cape, boots, brown crossbody satchel",
    "signature_detail": "a small brass compass",
    "continuity": "same face, same hairstyle, same outfit, same body proportions, same identity, same pastel palette in every panel"
  },
  "mandatory_rules": [
    "This must read as one continuous four-shot sequence from the same magical candy-world film scene.",
    "The child explorer must be clearly visible in every single panel, including panel 1.",
    "Panel 1 must not become an empty environment-only shot.",
    "The story must stay entirely inside the candy valley world.",
    "No futuristic ruins, no abandoned cars, no skyscrapers, no dark apocalypse, no ancient Chinese city.",
    "Each panel must have different cinematic emphasis and clear narrative progression."
  ],
  "storyboard_panels": [
    {
      "panel": "top_left",
      "shot": "wide establishing shot with character present",
      "must_have": [
        "same child explorer clearly visible in the foreground",
        "chocolate river",
        "cake towers and candy hills"
      ],
      "description": "The child explorer enters the magical candy valley for the first time. He must be clearly visible in the foreground, full body or medium full-body, as the central subject. Chocolate rivers, cake towers, sugar paths, candy hills, and cotton candy clouds fill the environment."
    },
    {
      "panel": "top_right",
      "shot": "medium full-body walking shot",
      "must_have": [
        "same child explorer walking on a sugar road",
        "candy valley still visible",
        "compass and satchel retained"
      ],
      "description": "The same child walks along a glossy sugar road beside a flowing chocolate river. Candy plants and pastel sweets line the path. His cape, satchel, and brass compass remain visible."
    },
    {
      "panel": "bottom_left",
      "shot": "close medium magical discovery shot",
      "must_have": [
        "same child explorer kneeling or leaning beside a glowing cake doorway",
        "brass compass clearly visible",
        "warm magical light illuminating his face"
      ],
      "description": "The same child discovers a glowing cake doorway hidden inside a dessert tower. He kneels beside it and holds up the brass compass. The glowing doorway is large, bright, and clearly the key magical object of the story."
    },
    {
      "panel": "bottom_right",
      "shot": "heroic magical reaction wide shot",
      "must_have": [
        "same child explorer reacting to the activated doorway",
        "the glowing cake doorway or sugar-light source still visible",
        "spiral sugar light in the air"
      ],
      "description": "The cake doorway activates and sends a spiral of glowing sugar light into the sky. The same child reacts with wonder and steps forward. The magical source must still be visible so the connection to panel 3 is obvious. This should not be just another generic walking shot; it must show a clear magical consequence."
    }
  ],
  "final_requirement": "The four panels must feel like one coherent candy-fantasy storyboard sequence, with strong continuity of character, pastel candy-world environment, magical event progression, and emotional storytelling."
}
